liquid:
{%- assign runId = '' -%}
{%- assign count = 0 -%}
{%- assign observedReady = false -%}
{%- assign valid = true -%}
{%- assign error = 'Invalid input or required response shape.' -%}
{%- assign p = nil -%}
{%- assign hasInput = apiEaseParameters | has_key: 'liquidParams' -%}
{%- if hasInput -%}
{%- assign p = apiEaseParameters.liquidParams -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = p | has_key: 'productId' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = p.productId | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
{%- unless p.productId != '' -%}
{%- assign valid = false -%}
{%- assign error = "productId must not be empty" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = p | has_key: 'expectedImages' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = p.expectedImages | is_type: 'integer' -%}
{%- endif -%}
{%- assign mediaCount = 0 -%}
{%- assign ready = true -%}
{%- assign pages = 0 -%}
{%- assign hasMore = true -%}
{%- assign cursor = nil -%}
{%- assign cursors = '' | split: '' -%}
{%- while hasMore and valid -%}
{%- call {"requestId":"read-product-media-page","bodyEmbedded":{"variables":{"productId":{{ p.productId | json }},"after":{{ cursor | json }}}}} as r -%}
{%- if valid -%}
{%- assign valid = r | has_key: 'status' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.status | is_type: 'integer' -%}
{%- endif -%}
{%- if valid -%}
{%- unless r.status >= 200 and r.status < 300 -%}
{%- assign valid = false -%}
{%- assign error = "Saved request execution failed" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r | has_key: 'data' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data | is_type: 'object' -%}
{%- endif -%}
{%- if valid -%}
{%- assign graphErrors = r.data | map: 'errors' | first | default: '' -%}
{%- assign errorCount = graphErrors | size -%}
{%- endif -%}
{%- if valid -%}
{%- unless errorCount == 0 -%}
{%- assign valid = false -%}
{%- assign error = "Shopify GraphQL errors" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data | has_key: 'data' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data | is_type: 'object' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data | has_key: 'product' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product | is_type: 'object' -%}
{%- endif -%}
{%- if valid -%}
{%- unless r.data.data.product.id == p.productId -%}
{%- assign valid = false -%}
{%- assign error = "Media product identity mismatch" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product | has_key: 'media' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media | is_type: 'object' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media | has_key: 'nodes' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media.nodes | is_type: 'array' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media | has_key: 'pageInfo' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media.pageInfo | is_type: 'object' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media.pageInfo | has_key: 'hasNextPage' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media.pageInfo.hasNextPage | is_type: 'boolean' -%}
{%- endif -%}
{%- if valid -%}
{%- assign hasMore = r.data.data.product.media.pageInfo.hasNextPage -%}
{%- endif -%}
{%- if valid -%}
{%- if hasMore -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media.pageInfo | has_key: 'endCursor' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = r.data.data.product.media.pageInfo.endCursor | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
{%- unless r.data.data.product.media.pageInfo.endCursor != '' -%}
{%- assign valid = false -%}
{%- assign error = "endCursor must not be empty" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- assign cursor = r.data.data.product.media.pageInfo.endCursor -%}
{%- if cursors contains cursor -%}
{%- assign valid = false -%}
{%- assign error = 'Repeated pagination cursor.' -%}
{%- endif -%}
{%- assign cursorSingle = r.data.data.product.media.pageInfo | map: 'endCursor' -%}
{%- assign cursors = cursors | concat: cursorSingle -%}
{%- endif -%}
{%- endif -%}
{%- endif -%}
{%- if valid -%}
{%- assign pages = pages | plus: 1 -%}
{%- for m in r.data.data.product.media.nodes -%}
{%- if valid -%}
{%- assign valid = m | has_key: 'status' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = m.status | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
{%- unless m.status != '' -%}
{%- assign valid = false -%}
{%- assign error = "status must not be empty" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = m | has_key: 'mediaErrors' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = m.mediaErrors | is_type: 'array' -%}
{%- endif -%}
{%- if valid -%}
{%- assign mediaErrorCount = m.mediaErrors | size -%}
{%- endif -%}
{%- if valid -%}
{%- unless m.status != 'FAILED' and mediaErrorCount == 0 -%}
{%- assign valid = false -%}
{%- assign error = "Image processing failed" -%}
{%- endunless -%}
{%- endif -%}
{%- if valid -%}
{%- if m.mediaContentType == 'IMAGE' -%}
{%- assign mediaCount = mediaCount | plus: 1 -%}
{%- if m.status != 'READY' -%}
{%- assign ready = false -%}
{%- else -%}
{%- if valid -%}
{%- assign valid = m | has_key: 'image' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = m.image | is_type: 'object' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = m.image | has_key: 'url' -%}
{%- endif -%}
{%- if valid -%}
{%- assign valid = m.image.url | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
{%- unless m.image.url != '' -%}
{%- assign valid = false -%}
{%- assign error = "url must not be empty" -%}
{%- endunless -%}
{%- endif -%}
{%- endif -%}
{%- endif -%}
{%- endif -%}
{%- endfor -%}
{%- endif -%}
{%- endwhile -%}
{%- if valid -%}
{%- if mediaCount != p.expectedImages -%}
{%- assign ready = false -%}
{%- endif -%}
{%- endif -%}
{%- if valid -%}
{"success":true,"ready":{{ ready | json }},"imageCount":{{ mediaCount | json }},"pages":{{ pages | json }},"error":null}{%- else -%}
{ "success":false,"error":{{ error | json }} }{%- endif -%}
